class SQLiteSessionStore extends session.Store {
  constructor(client) { super(); this.client = client; this.client.exec("CREATE TABLE IF NOT EXISTS sessions(sid TEXT PRIMARY KEY,sess TEXT NOT NULL,expire INTEGER NOT NULL)"); this.client.prepare("DELETE FROM sessions WHERE expire<=?").run(Date.now()) }
  get(sid, cb) { try { const row = this.client.prepare("SELECT sess,expire FROM sessions WHERE sid=?").get(sid); if (!row || row.expire <= Date.now()) { if (row) this.destroy(sid, () => { }); return cb(null, null) } cb(null, JSON.parse(row.sess)) } catch (e) { cb(e) } }
  set(sid, sess, cb) { try { const expire = sess.cookie && sess.cookie.expires ? new Date(sess.cookie.expires).getTime() : Date.now() + 1000 * 60 * 60 * 8; this.client.prepare("INSERT INTO sessions(sid,sess,expire) VALUES(?,?,?) ON CONFLICT(sid) DO UPDATE SET sess=excluded.sess,expire=excluded.expire").run(sid, JSON.stringify(sess), expire); cb && cb(null) } catch (e) { cb && cb(e) } }
  touch(sid, sess, cb) { try { const expire = sess.cookie && sess.cookie.expires ? new Date(sess.cookie.expires).getTime() : Date.now() + 1000 * 60 * 60 * 8; this.client.prepare("UPDATE sessions SET expire=? WHERE sid=?").run(expire, sid); cb && cb(null) } catch (e) { cb && cb(e) } }
  destroy(sid, cb) { try { this.client.prepare("DELETE FROM sessions WHERE sid=?").run(sid); cb && cb(null) } catch (e) { cb && cb(e) } }
  clear(cb) { try { this.client.prepare("DELETE FROM sessions").run(); cb && cb(null) } catch (e) { cb && cb(e) } }
  length(cb) { try { cb(null, this.client.prepare("SELECT COUNT(*) c FROM sessions").get().c) } catch (e) { cb(e) } }
  all(cb) { try { const rows = this.client.prepare("SELECT sess FROM sessions WHERE expire>? ").all(Date.now()).map(x => JSON.parse(x.sess)); cb(null, rows) } catch (e) { cb(e) } }
}
