function seed() {
  const adminEmail = (process.env.ADMIN_EMAIL || "admin@imobpro.local").toLowerCase();
  if (!db.prepare("SELECT id FROM users WHERE lower(email)=lower(?)").get(adminEmail)) db.prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)").run("Administrador", adminEmail, bcrypt.hashSync(process.env.ADMIN_PASSWORD || "admin123", 12), "admin");
  if (db.prepare("SELECT COUNT(*) c FROM properties").get().c === 0) {
    const admin = db.prepare("SELECT id FROM users WHERE role='admin' ORDER BY id LIMIT 1").get(); const s = db.prepare("INSERT INTO properties(owner_id,title,type,purpose,price,city,neighborhood,address,area,bedrooms,suites,bathrooms,parking,condo,iptu,description,features,status,cover_image) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");
    s.run(admin.id, "Apartamento sofisticado no Meireles", "Apartamento", "venda", 895000, "Fortaleza", "Meireles", "Av. Beira-Mar, 000", 118, 3, 2, 3, 2, 980, 2400, "Apartamento amplo, iluminado e pronto para morar, com ambientes integrados e excelente localização.", "Varanda|Ar-condicionado|Elevador|Piscina|Academia|Portaria|Mobiliado", "published", "https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1400&q=85");
    s.run(admin.id, "Casa contemporânea com piscina", "Casa", "venda", 1250000, "Fortaleza", "Cocó", "Rua Exemplo, 000", 260, 4, 3, 5, 4, 0, 0, "Casa contemporânea com área externa, piscina e espaços amplos para a família.", "Piscina|Jardim|Churrasqueira|Ar-condicionado|Closet|Área gourmet", "published", "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=85");
    s.run(admin.id, "Apartamento para alugar na Aldeota", "Apartamento", "aluguel", 3200, "Fortaleza", "Aldeota", "Rua Exemplo, 000", 82, 2, 1, 2, 1, 650, 0, "Apartamento funcional em região valorizada, com boa mobilidade e serviços próximos.", "Elevador|Portaria|Varanda|Academia|Pet friendly", "published", "https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1400&q=85");
  }
  const defs = { company_name: "Imob Pro", whatsapp: "5585999999999", phone: "(85) 99999-9999", email: "contato@imobpro.local", city: "Fortaleza - CE", primary_color: "#B08D57", hero_title: "Encontre o lugar onde sua próxima história começa.", hero_subtitle: "Uma experiência imobiliária completa para comprar, alugar e anunciar.", instagram: "", facebook: "", linkedin: "" }; const st = db.prepare("INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)"); Object.entries(defs).forEach(([k, v]) => st.run(k, v));
} seed();
const storage = multer.diskStorage({ destination: uploadDir, filename: (_, f, cb) => cb(null, crypto.randomUUID() + path.extname(f.originalname).toLowerCase()) });
const upload = multer({ storage, limits: { fileSize: 10 * 1024 * 1024 }, fileFilter: (_, f, cb) => cb(/image\/(jpeg|png|webp|jpg)/.test(f.mimetype) ? null : new Error("Apenas JPG, PNG ou WEBP.")) });
const roles = { admin: ["admin", "manager", "editor", "agent", "owner", "customer"], manager: ["manager", "editor", "agent", "owner", "customer"], editor: ["editor"], agent: ["agent", "customer"], owner: ["owner"], customer: ["customer"] };
function auth(req, res, next) { if (!req.session.user) return res.status(401).json({ error: "Não autenticado." }); next() }
function staff(req, res, next) { if (!req.session.user || !["admin", "manager", "editor", "agent"].includes(req.session.user.role)) return res.status(403).json({ error: "Acesso negado." }); next() }
function manage(req, res, next) { if (!req.session.user || !["admin", "manager", "editor"].includes(req.session.user.role)) return res.status(403).json({ error: "Acesso negado." }); next() }
function agentOnly(req, res, next) { if (!req.session.user || req.session.user.role !== "agent") return res.status(403).json({ error: "Acesso restrito aos atendentes." }); next() }
function getSettings() { return Object.fromEntries(db.prepare("SELECT key,value FROM settings").all().map(x => [x.key, x.value])) }
function publicUser(u) { return u && { id: u.id, name: u.name, email: u.email, role: u.role, phone: u.phone || "" } }
function normalize(p) { if (!p) return null; p.features = p.features ? p.features.split("|").filter(Boolean) : []; p.images = db.prepare("SELECT id,filename,sort_order FROM property_images WHERE property_id=? ORDER BY sort_order,id").all(p.id); if (p.cover_image && !/^https?:\/\//.test(p.cover_image)) p.cover_image = "/uploads/" + p.cover_image; return p }
function log(req, action, type, id, details = "") { db.prepare("INSERT INTO activity_log(user_id,entity_type,entity_id,action,details) VALUES(?,?,?,?,?)").run(req.session.user?.id || null, type, id, action, details) }
function notify(userId, title, message, type = "info") { if (userId) db.prepare("INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)").run(userId, title, message, type) }
const mailer = process.env.SMTP_HOST ? nodemailer.createTransport({ host: process.env.SMTP_HOST, port: Number(process.env.SMTP_PORT || 587), secure: String(process.env.SMTP_SECURE) === "true", auth: process.env.SMTP_USER ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS } : undefined }) : null;
async function sendMail(to, subject, text) { if (!mailer || !to) return false; try { await mailer.sendMail({ from: process.env.MAIL_FROM || process.env.SMTP_USER, to, subject, text }); return true } catch (e) { console.error("E-mail não enviado:", e.message); return false } }
function propertyPayload(b, p = {}) { return [b.title ?? p.title, b.type ?? p.type, b.purpose ?? p.purpose, Number(b.price ?? p.price) || 0, b.city ?? p.city, b.neighborhood ?? p.neighborhood, b.address ?? p.address ?? "", Number(b.area ?? p.area) || 0, Number(b.bedrooms ?? p.bedrooms) || 0, Number(b.suites ?? p.suites) || 0, Number(b.bathrooms ?? p.bathrooms) || 0, Number(b.parking ?? p.parking) || 0, Number(b.condo ?? p.condo) || 0, Number(b.iptu ?? p.iptu) || 0, b.description ?? p.description ?? "", Array.isArray(b.features) ? b.features.join("|") : (b.features ?? p.features ?? ""), b.video_url ?? p.video_url ?? "", b.latitude ?? p.latitude ?? null, b.longitude ?? p.longitude ?? null] }

app.get("/api/settings", (_, res) => res.json(getSettings()));
app.get("/api/auth/me", (req, res) => res.json(req.session.user || null));
app.post("/api/auth/login", (req, res) => {
  const email = String(req.body.email || "").trim().toLowerCase(); const password = String(req.body.password || ""); let u = db.prepare("SELECT * FROM users WHERE lower(email)=?").get(email);
  // Em desenvolvimento, as credenciais administrativas definidas no .env também funcionam
  // para recuperar um banco local antigo sem apagar usuários, imóveis ou leads.
  const recoveryPassword = process.env.ADMIN_PASSWORD || (!isProd ? "admin123" : "");
  if (u && !bcrypt.compareSync(password, u.password_hash) && u.role === "admin" && recoveryPassword && password === recoveryPassword && (!isProd || process.env.ADMIN_SYNC_PASSWORD === "true")) {
    db.prepare("UPDATE users SET password_hash=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(bcrypt.hashSync(password, 12), u.id);
    u = db.prepare("SELECT * FROM users WHERE id=?").get(u.id);
  }
  if (!u || !bcrypt.compareSync(password, u.password_hash)) return res.status(401).json({ error: "E-mail ou senha inválidos." });
  req.session.regenerate(err => { if (err) return res.status(500).json({ error: "Não foi possível iniciar a sessão." }); req.session.user = publicUser(u); log(req, "login", "user", u.id); res.json(req.session.user) })
});
app.post("/api/auth/register", (req, res) => { const { name, email, password, phone = "" } = req.body || {}; if (!name || !email || !password || password.length < 8) return res.status(400).json({ error: "Nome, e-mail e senha de pelo menos 8 caracteres são obrigatórios." }); try { const r = db.prepare("INSERT INTO users(name,email,password_hash,role,phone) VALUES(?,?,?,?,?)").run(name.trim(), email.trim().toLowerCase(), bcrypt.hashSync(password, 12), "customer", phone); const u = db.prepare("SELECT * FROM users WHERE id=?").get(r.lastInsertRowid); req.session.regenerate(err => { if (err) return res.status(500).json({ error: "Não foi possível iniciar a sessão." }); req.session.user = publicUser(u); res.status(201).json(req.session.user) }) } catch (e) { res.status(409).json({ error: "Este e-mail já está cadastrado." }) } });
app.post("/api/auth/logout", (req, res) => req.session.destroy(() => res.json({ ok: true })));
app.post("/api/auth/admin-recover", (req, res) => {
  if (isProd && process.env.ADMIN_RECOVERY_ENABLED !== "true") return res.status(404).json({ error: "Rota não disponível." });
  const email = String(req.body.email || "").trim().toLowerCase();
  const password = String(req.body.password || "");
  const recoveryKey = String(req.body.recoveryKey || "");
  const expectedKey = process.env.ADMIN_RECOVERY_KEY || (!isProd ? "imobpro-local-recovery" : "");
  if (!email || password.length < 10 || !expectedKey || recoveryKey !== expectedKey) return res.status(403).json({ error: "Dados de recuperação inválidos." });
  const u = db.prepare("SELECT * FROM users WHERE lower(email)=? AND role='admin'").get(email);
  if (!u) return res.status(404).json({ error: "Administrador não encontrado." });
  db.prepare("UPDATE users SET password_hash=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(bcrypt.hashSync(password, 12), u.id);
  db.prepare("DELETE FROM sessions").run();
  res.json({ ok: true, message: "Senha administrativa redefinida. Faça login novamente." });
});

app.post("/api/auth/change-password", auth, (req, res) => { const { currentPassword, newPassword } = req.body || {}; const u = db.prepare("SELECT * FROM users WHERE id=?").get(req.session.user.id); if (!bcrypt.compareSync(currentPassword || "", u.password_hash)) return res.status(400).json({ error: "Senha atual incorreta." }); if (!newPassword || newPassword.length < 6) return res.status(400).json({ error: "A nova senha precisa ter pelo menos 6 caracteres." }); db.prepare("UPDATE users SET password_hash=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(bcrypt.hashSync(newPassword, 12), u.id); log(req, "change_password", "user", u.id); res.json({ ok: true }) });
app.post("/api/auth/forgot-password", (req, res) => { const email = String(req.body.email || "").trim().toLowerCase(); const u = db.prepare("SELECT id FROM users WHERE lower(email)=?").get(email); let devToken = null; if (u) { db.prepare("UPDATE password_reset_tokens SET used_at=CURRENT_TIMESTAMP WHERE user_id=? AND used_at IS NULL").run(u.id); const raw = crypto.randomBytes(32).toString("hex"); db.prepare("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,?)").run(u.id, crypto.createHash("sha256").update(raw).digest("hex"), new Date(Date.now() + 30 * 60 * 1000).toISOString()); devToken = raw; } const payload = { ok: true, message: "Se o e-mail existir, um link de recuperação foi preparado." }; if (u && mailer) { const link = `${process.env.APP_URL || `http://localhost:${PORT}`}/?reset=${devToken}`; sendMail(email, "Redefinição de senha — Imob Pro", `Use este código para redefinir sua senha: ${devToken}\n\nLink: ${link}\n\nO código expira em 30 minutos.`) } if (process.env.NODE_ENV !== "production" && devToken) payload.devToken = devToken; res.json(payload) });
app.post("/api/auth/reset-password", (req, res) => { const token = String(req.body.token || ""); const password = String(req.body.password || ""); if (token.length < 20 || password.length < 8) return res.status(400).json({ error: "Token inválido ou senha muito curta." }); const hash = crypto.createHash("sha256").update(token).digest("hex"); const row = db.prepare("SELECT * FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>? ").get(hash, new Date().toISOString()); if (!row) return res.status(400).json({ error: "Token inválido ou expirado." }); db.prepare("UPDATE users SET password_hash=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(bcrypt.hashSync(password, 12), row.user_id); db.prepare("UPDATE password_reset_tokens SET used_at=CURRENT_TIMESTAMP WHERE id=?").run(row.id); res.json({ ok: true, message: "Senha redefinida com sucesso." }) });

app.get("/api/properties", (req, res) => { const q = req.query; let sql = "SELECT p.*,u.name owner_name FROM properties p LEFT JOIN users u ON u.id=p.owner_id WHERE 1=1", a = []; const privileged = req.session.user && ["admin", "manager", "editor", "agent"].includes(req.session.user.role); if (!privileged) sql += " AND p.status='published'"; if (q.status) { sql += " AND p.status=?"; a.push(q.status) } if (q.purpose) { sql += " AND p.purpose=?"; a.push(q.purpose) } if (q.type) { sql += " AND p.type=?"; a.push(q.type) } if (q.city) { sql += " AND lower(p.city) LIKE lower(?)"; a.push("%" + q.city + "%") } if (q.neighborhood) { sql += " AND lower(p.neighborhood) LIKE lower(?)"; a.push("%" + q.neighborhood + "%") } if (q.minPrice) { sql += " AND p.price>=?"; a.push(Number(q.minPrice)) } if (q.maxPrice) { sql += " AND p.price<=?"; a.push(Number(q.maxPrice)) } if (q.bedrooms) { sql += " AND p.bedrooms>=?"; a.push(Number(q.bedrooms)) } if (q.parking) { sql += " AND p.parking>=?"; a.push(Number(q.parking)) } if (q.q) { sql += " AND (lower(p.title) LIKE lower(?) OR lower(p.neighborhood) LIKE lower(?) OR lower(p.city) LIKE lower(?))"; const s = "%" + q.q + "%"; a.push(s, s, s) } sql += " ORDER BY p.updated_at DESC LIMIT 100"; res.json(db.prepare(sql).all(...a).map(normalize)) });
app.get("/api/properties/:id", (req, res) => { const p = normalize(db.prepare("SELECT p.*,u.name owner_name FROM properties p LEFT JOIN users u ON u.id=p.owner_id WHERE p.id=?").get(req.params.id)); if (!p) return res.status(404).json({ error: "Imóvel não encontrado." }); if (p.status !== "published" && !req.session.user) return res.status(404).json({ error: "Imóvel não encontrado." }); res.json(p) });
app.post("/api/leads", (req, res) => { const b = req.body || {}; if (!b.name || !b.whatsapp) return res.status(400).json({ error: "Nome e WhatsApp são obrigatórios." }); let customerId = req.session.user?.role === "customer" ? req.session.user.id : null; if (!customerId && b.email) { const existing = db.prepare("SELECT id FROM users WHERE lower(email)=lower(?)").get(b.email); customerId = existing?.id || null } const r = db.prepare("INSERT INTO leads(customer_id,name,whatsapp,email,property_id,message,source) VALUES(?,?,?,?,?,?,?)").run(customerId, b.name, b.whatsapp, b.email || "", b.property_id || null, b.message || "", b.source || "site"); const agents = db.prepare("SELECT id FROM users WHERE role='agent' ORDER BY id").all(); if (agents.length) { const cursor = Number(db.prepare("SELECT value FROM settings WHERE key='lead_rr_cursor'").get()?.value || 0); const agent = agents[cursor % agents.length]; db.prepare("INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").run("lead_rr_cursor", String(cursor + 1)); db.prepare("UPDATE leads SET assigned_to=? WHERE id=?").run(agent.id, r.lastInsertRowid); notify(agent.id, "Novo lead", "Um novo cliente demonstrou interesse.", "lead"); db.prepare("INSERT INTO tasks(user_id,lead_id,title,priority) VALUES(?,?,?,?)").run(agent.id, r.lastInsertRowid, "Fazer primeiro contato com novo lead", "high"); } res.status(201).json({ id: r.lastInsertRowid }) });

