app.post("/api/owner/properties", auth, (req, res) => { if (req.session.user.role !== "owner") return res.status(403).json({ error: "Acesso negado." }); const b = req.body || {}; if (!b.title || !b.type || !b.purpose || !b.city || !b.neighborhood) return res.status(400).json({ error: "Preencha título, tipo, finalidade, cidade e bairro." }); const vals = propertyPayload(b); const r = db.prepare("INSERT INTO properties(owner_id,title,type,purpose,price,city,neighborhood,address,area,bedrooms,suites,bathrooms,parking,condo,iptu,description,features,video_url,latitude,longitude,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(req.session.user.id, ...vals, "pending"); notify(req.session.user.id, "Anúncio enviado", "Seu imóvel está aguardando análise.", "property"); res.status(201).json(normalize(db.prepare("SELECT * FROM properties WHERE id=?").get(r.lastInsertRowid))) });
app.patch("/api/owner/properties/:id", auth, (req, res) => { if (req.session.user.role !== "owner") return res.status(403).json({ error: "Acesso negado." }); const p = db.prepare("SELECT * FROM properties WHERE id=?").get(req.params.id); if (!p) return res.status(404).json({ error: "Imóvel não encontrado." }); if (p.owner_id !== req.session.user.id) return res.status(403).json({ error: "Você só pode editar seus próprios anúncios." }); const v = propertyPayload(req.body, p); db.prepare("UPDATE properties SET title=?,type=?,purpose=?,price=?,city=?,neighborhood=?,address=?,area=?,bedrooms=?,suites=?,bathrooms=?,parking=?,condo=?,iptu=?,description=?,features=?,video_url=?,latitude=?,longitude=?,status='pending',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(...v, p.id); notify(req.session.user.id, "Alteração enviada", "Seu anúncio voltou para análise.", "property"); res.json(normalize(db.prepare("SELECT * FROM properties WHERE id=?").get(p.id))) });

app.post("/api/owner/properties/:id/images", auth, upload.array("images", 20), (req, res) => { if (req.session.user.role !== "owner") return res.status(403).json({ error: "Acesso negado." }); const propertyId = Number(req.params.id); const prop = db.prepare("SELECT id,owner_id FROM properties WHERE id=?").get(propertyId); if (!prop) return res.status(404).json({ error: "Imóvel não encontrado." }); if (prop.owner_id !== req.session.user.id) return res.status(403).json({ error: "Você só pode adicionar imagens aos seus próprios anúncios." }); const files = req.files || []; if (!files.length) return res.status(400).json({ error: "Selecione pelo menos uma imagem." }); let max = db.prepare("SELECT COALESCE(MAX(sort_order),0) m FROM property_images WHERE property_id=?").get(propertyId).m; const st = db.prepare("INSERT INTO property_images(property_id,filename,sort_order) VALUES(?,?,?)"); db.transaction(fsx => fsx.forEach((f, i) => st.run(propertyId, f.filename, max + i + 1)))(files); if (!prop.cover_image) db.prepare("UPDATE properties SET cover_image=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(files[0].filename, propertyId); notify(req.session.user.id, "Fotos adicionadas", "As novas imagens foram anexadas ao seu anúncio.", "property"); res.json(normalize(db.prepare("SELECT * FROM properties WHERE id=?").get(propertyId))) });

