app.get("/api/messages/contacts", auth, (req, res) => {
  const r = req.session.user.role;
  if (["admin", "manager", "editor", "agent"].includes(r)) {
    return res.json(db.prepare("SELECT id,name,email,role,phone FROM users WHERE id<>? AND role IN ('customer','owner','agent','manager','admin') ORDER BY name LIMIT 200").all(req.session.user.id));
  }
  const contacts = db.prepare("SELECT id,name,email,role,phone FROM users WHERE role IN ('admin','manager','agent') ORDER BY CASE role WHEN 'admin' THEN 0 WHEN 'manager' THEN 1 ELSE 2 END,name LIMIT 20").all();
  res.json(contacts);
});
app.get("/api/messages", auth, (req, res) => {
  const uid = req.session.user.id, other = Number(req.query.with || 0);
  let sql = "SELECT m.*,s.name sender_name,r.name recipient_name,p.title property_title FROM messages m LEFT JOIN users s ON s.id=m.sender_id LEFT JOIN users r ON r.id=m.recipient_id LEFT JOIN properties p ON p.id=m.property_id WHERE (m.sender_id=? AND m.recipient_id=?) OR (m.sender_id=? AND m.recipient_id=?) ORDER BY m.created_at ASC LIMIT 200";
  if (!other) return res.json([]);
  const rows = db.prepare(sql).all(uid, other, other, uid);
  db.prepare("UPDATE messages SET read_at=CURRENT_TIMESTAMP WHERE recipient_id=? AND sender_id=? AND read_at IS NULL").run(uid, other);
  res.json(rows);
});
app.get("/api/messages/unread", auth, (req, res) => res.json({ count: db.prepare("SELECT COUNT(*) c FROM messages WHERE recipient_id=? AND read_at IS NULL").get(req.session.user.id).c }));
app.post("/api/messages", auth, (req, res) => { if (!req.body.recipient_id || !req.body.body) return res.status(400).json({ error: "Destinatário e mensagem são obrigatórios." }); const recipient = db.prepare("SELECT id FROM users WHERE id=?").get(req.body.recipient_id); if (!recipient) return res.status(404).json({ error: "Destinatário não encontrado." }); const body = String(req.body.body).trim(); if (body.length > 2000) return res.status(400).json({ error: "A mensagem pode ter no máximo 2.000 caracteres." }); const r = db.prepare("INSERT INTO messages(sender_id,recipient_id,property_id,lead_id,body) VALUES(?,?,?,?,?)").run(req.session.user.id, req.body.recipient_id, req.body.property_id || null, req.body.lead_id || null, body); notify(req.body.recipient_id, "Nova mensagem", `Você recebeu uma nova mensagem de ${req.session.user.name}.`, "message"); log(req, "send", "message", r.lastInsertRowid); res.status(201).json({ id: r.lastInsertRowid, created_at: new Date().toISOString() }) });

