app.post("/api/me/privacy-requests", auth, (req, res) => { const type = String(req.body.type || "access"); const allowed = ["access", "correction", "deletion", "portability", "revocation", "information"]; if (!allowed.includes(type)) return res.status(400).json({ error: "Tipo de solicitação inválido." }); const r = db.prepare("INSERT INTO privacy_requests(user_id,type,details) VALUES(?,?,?)").run(req.session.user.id, type, String(req.body.details || "")); notify(req.session.user.id, "Solicitação registrada", "Sua solicitação de privacidade foi registrada para análise.", "privacy"); res.status(201).json({ id: r.lastInsertRowid }) });
