app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError || err?.message === "Apenas JPG, PNG ou WEBP.") return res.status(400).json({ error: err.code === "LIMIT_FILE_SIZE" ? "Cada imagem pode ter no máximo 10 MB." : err.message });
  console.error(err);
  if (res.headersSent) return next(err);
  res.status(500).json({ error: isProd ? "Erro interno do servidor." : (err.message || "Erro interno do servidor.") });
});

